// Poor, missing a hashcode() method

public class Bar {

	public boolean equals(Object object) {
		return true;
	}

}

// Poor, missing an equals() method

public class Baz {

	public int hashCode() {
		return 0;
	}

}

// Perfect, both methods are provided

public class Foo {

	public boolean equals(Object object) {
		return true;
	}

	public int hashCode() {
		return 0;
	}

}
